return {
  focus: {
    hook: "activated",
    rateLimit: "oncePerRound",
    cost: { resource: "resolve", amount: 1 },
    available: (H, actor) => H.zone.threatIn(H.zone.of(actor)) > 0,
    run: async (H, actor, ctx) => {
      await H.effects.apply([
        { type: "confirm", title: "Exemplar", message: "Spend <strong>1 Resolve</strong> to Focus?", yesLabel: "Spend Resolve" },
        { type: "focus", stopIfUnchanged: true },
        { type: "chatNotice", message: "<strong>{actor}</strong> spends <strong>1 Resolve</strong> to Focus (Exemplar)." },
      ], ctx);
      return !ctx._cancelled;
    },
  },
};
